import"./chunk-2NFLSA4Y.js";var i={seesaw:{theory:{concept:"[[A lever is a rigid body that can turn about a fixed support, the pivot; a seesaw is a lever.]] The turning effect of a force is its moment (torque), \u03C4 = F \xB7 d, where the lever arm d is the shortest distance from the pivot to the line along which the force acts. A lever is in balance when the sum of the moments turning it clockwise equals the sum of the moments turning it anticlockwise."},section:{torque:{title:"Torque: the turning effect",text:"[[A force turns a lever more strongly the further from the pivot it acts.]] A door handle is far from the hinges for this reason \u2014 try pushing a door near its hinges and feel how hard it is."},balance:{title:"When is it balanced?",text:"The seesaw is balanced when the torques on both sides are equal: [[m\u2081 \xB7 d\u2081 = m\u2082 \xB7 d\u2082]]. Then it can stay still in any position. If one torque is bigger, that side goes down until it touches the ground. The board here turns about its middle, so its own weight does not tip it either way."},leverArm:{title:"A light child can win",text:"Mass is not everything. A 20 kg child 1.5 m from the pivot balances a 30 kg child sitting 1 m away: 20 \xB7 1.5 = 30 \xB7 1. Sit the light child further out and they can even lift the heavier one. This is how a short push on a long handle can lift something heavy."},gravity:{title:"Balance does not depend on gravity",text:"Both weights are m \xB7 g, so g appears on both sides of the balance condition and cancels out. [[A balanced seesaw on the Earth is balanced on the Moon too.]] Gravity changes only how fast an unbalanced seesaw tips."},levers:{title:"Levers everywhere",text:"A seesaw is a first-class lever: the pivot is between the two forces, like in scissors and pliers. In a wheelbarrow or a nutcracker the load is between the pivot and your hand; in tweezers and in your forearm your force is between the pivot and the load. Each type trades force for distance in its own way."},archimedes:{title:"Archimedes and the lever",text:'Archimedes of Syracuse (3rd century BC) worked out the law of the lever: the weights are in balance when they are inversely proportional to their distances from the pivot. He is said to have boasted: "Give me a place to stand, and I will move the Earth" \u2014 with a long enough lever, a small force can balance any weight.'},check:{title:"Check your understanding",text:"A 30 kg child sits 1.2 m from the pivot. Where must a 20 kg child sit to balance? (1.8 m.) Both children move twice as far out. Is it still balanced? (Yes.) A balanced seesaw is taken to the Moon. Does it stay balanced? (Yes.) Which side goes down: 40 kg at 1 m or 25 kg at 2 m? (The 25 kg side: 50 > 40.) Test each answer in the simulation."}},formula:{torque:"Torque (turning effect of a force)",balance:"Balance condition",weight:"Weight",rotation:"Rotation: moment of inertia \xD7 angular acceleration"},variable:{mass:"Mass of a load",distance:"Distance from the pivot (lever arm)",force:"Force (here: weight)",torque:"Torque"},assumption:{rigid:"The board is stiff and turns around its middle, so its own weight does not tip it.",pointLoads:"Each load acts at one point on the board; the children sit still.",friction:"Friction in the pivot is ignored unless you add it (Advanced level).",ground:"When one end hits the ground the board bounces a little and stops."},param:{leftMass:"Left mass",leftDistance:"Left distance",rightMass:"Right mass",rightDistance:"Right distance",gravity:"Gravity",plankMass:"Board mass",pivotFriction:"Pivot friction",timeStep:"Simulation timestep"},hint:{gravity:"Does balance depend on gravity? Try the Moon.",plankMass:"A heavier board turns more slowly but does not change the balance.",pivotFriction:"Friction in the pivot slows the turning down."},measure:{angle:"Tilt angle",leftWeight:"Left weight",rightWeight:"Right weight",netTorque:"Net torque",angularVelocity:"Angular velocity",leftTorque:"Left torque",rightTorque:"Right torque"},view:{balanced:"Balanced"},graph:{angle:"Tilt angle vs time",angularVelocity:"Angular velocity vs time"},challenge:{balance:{title:"Perfect balance",description:"Balance the seesaw with two different masses so it stays level.",hint:"The heavier child must sit closer to the pivot: m\u2081 \xB7 d\u2081 = m\u2082 \xB7 d\u2082."},lightWins:{title:"Light beats heavy",description:"Make the right side go down even though its mass is at most half of the left mass.",hint:"Move the light load far from the pivot and the heavy one close to it."},moon:{title:"Balance on the Moon",description:"Set the Moon's gravity (1.62 m/s\xB2) and balance two different masses.",hint:"Gravity changes both weights by the same factor. Does that change the balance?"},slow:{title:"Gentle landing",description:"Make the seesaw take at least 3 seconds to touch the ground.",hint:"Make the torques almost equal, or add friction in the pivot."}}}},a={sim:i};export{a as default,i as sim};
